## 3. Практические примеры реализации

### Правило 1: Сравнение расстояний через квадрат величины (`sqrMagnitude`)

```csharp
using UnityEngine;

public sealed class DistanceOptimizer : MonoBehaviour
{
    [SerializeField] private Transform _target;
    [SerializeField] private float _triggerDistance = 5f;

    // НЕОПТИМАЛЬНО: Вычисляет квадратный корень при каждом вызове
    public bool IsTargetCloseNonOptimal()
    {
        float dist = Vector3.Distance(transform.position, _target.position);
        return dist < _triggerDistance;
    }

    // ОПТИМАЛЬНО: Исключает извлечение квадратного корня
    public bool IsTargetCloseOptimal()
    {
        float sqrDist = (transform.position - _target.position).sqrMagnitude;
        float sqrTrigger = _triggerDistance * _triggerDistance;
        return sqrDist < sqrTrigger;
    }
}
```

