### Правило 2 & 3: Удаление пустых методов и использование Update Manager

```csharp
using System.Collections.Generic;
using UnityEngine;

// Интерфейс для обновления без наследования от MonoBehaviour
public interface IUpdatable
{
    void UpdateTick(float deltaTime);
}

// Единый менеджер обновлений (висит на одном объекте сцены)
public sealed class UpdateManager : MonoBehaviour
{
    private readonly List<IUpdatable> _updatableObjects = new List<IUpdatable>();

    public void Register(IUpdatable obj) => _updatableObjects.Add(obj);
    public void Unregister(IUpdatable obj) => _updatableObjects.Remove(obj);

    private void Update()
    {
        float dt = Time.deltaTime;
        int count = _updatableObjects.Count;
        
        // Быстрый обход коллекции по индексу без аллокаций
        for (int i = 0; i < count; i++)
        {
            _updatableObjects[i].UpdateTick(dt);
        }
    }
}
```

