using UnityEngine;

public sealed class PhysicsCastOptimizer : MonoBehaviour
{
    private readonly RaycastHit[] _raycastResults = new RaycastHit[10];

    // НЕОПТИМАЛЬНО: Каждый кадр выделяет массив в куче под результаты
    public void ScanNonOptimal()
    {
        RaycastHit[] hits = Physics.RaycastAll(transform.position, transform.forward, 10f);
        for (int i = 0; i < hits.Length; i++)
        {
            ProcessHit(hits[i]);
        }
    }

    // ОПТИМАЛЬНО: Записывает результаты в заранее выделенный массив в стеке/поле
    public void ScanOptimal()
    {
        int hitCount = Physics.RaycastNonAlloc(transform.position, transform.forward, _raycastResults, 10f);
        for (int i = 0; i < hitCount; i++)
        {
            ProcessHit(_raycastResults[i]);
        }
    }

    private void ProcessHit(RaycastHit hit) { /* Логика */ }
}
```

