### Правило 7: Оптимизация конуса видимости (углов) через скалярное произведение (`Dot`)

```csharp
using UnityEngine;

public sealed class FieldOfViewOptimizer : MonoBehaviour
{
    [SerializeField] private Transform _target;
    [SerializeField] private float _fovAngle = 45f;

    // НЕОПТИМАЛЬНО: Использует тригонометрический арккосинус под капотом
    public bool IsTargetInConeNonOptimal()
    {
        Vector3 dirToTarget = (_target.position - transform.position).normalized;
        float angle = Vector3.Angle(transform.forward, dirToTarget);
        return angle < _fovAngle;
    }

    // ОПТИМАЛЬНО: Сравнение косинусов через скалярное произведение векторов
    public bool IsTargetInConeOptimal()
    {
        Vector3 dirToTarget = (_target.position - transform.position).normalized;
        
        // Скалярное произведение нормализованных векторов равно косинусу угла между ними
        float dotProduct = Vector3.Dot(transform.forward, dirToTarget);
        
        // Косинус целевого угла (можно кэшировать, если угол не меняется)
        float cosThreshold = Mathf.Cos(_fovAngle * Mathf.Deg2Rad);

        // Чем меньше угол, тем ближе косинус к 1
        return dotProduct > cosThreshold;
    }
}
```

