### Правило 8: Установка вместимости (Capacity) для списков

```csharp
using System.Collections.Generic;
using UnityEngine;

public sealed class ListCapacityOptimizer : MonoBehaviour
{
    // НЕОПТИМАЛЬНО: Вызывает частые перевыделения массивов в памяти при расширении
    public List<int> GenerateNumbersNonOptimal()
    {
        List<int> list = new List<int>();
        for (int i = 0; i < 1000; i++)
        {
            list.Add(i);
        }
        return list;
    }

    // ОПТИМАЛЬНО: Память под 1000 элементов выделяется одним куском
    public List<int> GenerateNumbersOptimal()
    {
        List<int> list = new List<int>(1000);
        for (int i = 0; i < 1000; i++)
        {
            list.Add(i);
        }
        return list;
    }
}
