### Правило 9: Кэширование Yield-инструкций в корутинах

```csharp
using System.Collections;
using UnityEngine;

public sealed class CoroutineOptimizer : MonoBehaviour
{
    private WaitForSeconds _cachedWait;

    private void Awake()
    {
        _cachedWait = new WaitForSeconds(0.2f);
    }

    // НЕОПТИМАЛЬНО: Аллоцирует новый WaitForSeconds в куче каждые 0.2 сек
    private IEnumerator FireRoutineNonOptimal()
    {
        while (true)
        {
            Shoot();
            yield return new WaitForSeconds(0.2f);
        }
    }

    // ОПТИМАЛЬНО: Использует переиспользуемую инструкцию из поля класса
    private IEnumerator FireRoutineOptimal()
    {
        while (true)
        {
            Shoot();
            yield return _cachedWait;
        }
    }

    private void Shoot() { }
}
```

