using UnityEngine;

public sealed class ConditionOrdering : MonoBehaviour
{
    private bool _isEasyCondition = false;

    // НЕОПТИМАЛЬНО: Тяжелый метод выполняется всегда, даже если легкое условие ложно
    public void ProcessNonOptimal()
    {
        if (HeavyCalculation() && _isEasyCondition)
        {
            DoSomething();
        }
    }

    // ОПТИМАЛЬНО: Тяжелый метод не запустится, если легкое условие ложно
    public void ProcessOptimal()
