#### Шаг 2.4: Интеграция передачи параметров в `SceneLoaderService`
Мы модифицируем метод загрузки. После окончания операции он ищет на сцене `Bootstrap` и вызывает `Initialize`. Изменяется файл `SceneLoaderService.cs`:

```csharp
using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;

public static class SceneLoaderService
{
    public static IEnumerator LoadSceneWithArgsCoroutine(
        string sceneName, 
        ISceneArgs args, 
        LoadingScreen loadingScreen)
    {
        loadingScreen.Show("Загрузка сцены...");
        
        AsyncOperation operation = SceneManager.LoadSceneAsync(sceneName, LoadSceneMode.Single);
        
        while (!operation.isDone)
        {
            yield return null;
        }

        // Поиск Bootstrap на новой сцене
        Bootstrap bootstrap = Object.FindAnyObjectByType<Bootstrap>();
        if (bootstrap != null)
        {
            bootstrap.Initialize(args);
        }
        else
        {
            Debug.LogWarning("No Bootstrap found on scene: " + sceneName);
        }
        
        loadingScreen.Hide();
    }
}
```

