using UnityEngine;
using UnityEngine.SceneManagement;

public class SpawnerHelper : MonoBehaviour
{
    [SerializeField] private GameObject _cubePrefab;
    [SerializeField] private string _targetEnvironmentSceneName = "Environment_Level1";

    public void SpawnObjectOnTargetScene()
    {
        // 1. Создаем объект на активной сцене по умолчанию
        GameObject spawnedObj = Instantiate(_cubePrefab, Vector3.zero, Quaternion.identity);

        // 2. Ищем целевую сцену по имени
        Scene targetScene = SceneManager.GetSceneByName(_targetEnvironmentSceneName);

        if (targetScene.isLoaded)
        {
            // 3. Перемещаем объект
            SceneManager.MoveGameObjectToScene(spawnedObj, targetScene);
            Debug.Log("Object moved to scene: " + _targetEnvironmentSceneName);
        }
        else
        {
            Debug.LogWarning("Target scene is not loaded! Object remains on active scene.");
        }
    }
}
```

