### Часть 4: Интеграция с пакетом Addressables и UniTask

На этом этапе мы полностью переписываем загрузчик на `UniTask` и подключаем систему `Addressables` для динамического управления памятью сцен.

#### Шаг 4.1: Скрипт Addressables-загрузчика `AddressablesSceneLoader`
Этот сервис использует `UniTask`, отслеживает хэндлы загруженных сцен и ведет подсчет ссылок, чтобы не грузить один и тот же ресурс повторно. Создается файл `AddressablesSceneLoader.cs`:

```csharp
using System.Collections.Generic;
using Cysharp.Threading.Tasks;
using UnityEngine;
using UnityEngine.AddressableAssets;
using UnityEngine.ResourceManagement.AsyncOperations;
using UnityEngine.ResourceManagement.ResourceProviders;
using UnityEngine.SceneManagement;

public static class AddressablesSceneLoader
{
    private class LoadedSceneData
    {
        public AsyncOperationHandle<SceneInstance> Handle;
        public int RefCount;

        public LoadedSceneData(AsyncOperationHandle<SceneInstance> handle)
        {
            Handle = handle;
            RefCount = 1;
        }
    }

    private static readonly Dictionary<string, LoadedSceneData> _loadedScenes = new Dictionary<string, LoadedSceneData>();

    public static async UniTask LoadSceneAsync(string sceneKey, LoadSceneMode loadMode = LoadSceneMode.Single)
    {
        // Если сцена уже загружается или загружена
        if (_loadedScenes.TryGetValue(sceneKey, out LoadedSceneData data))
        {
            data.RefCount++;
            Debug.Log("Scene " + sceneKey + " ref count increased to: " + data.RefCount);
            return;
        }

        Debug.Log("Loading Scene via Addressables: " + sceneKey);
        
        AsyncOperationHandle<SceneInstance> handle = Addressables.LoadSceneAsync(sceneKey, loadMode);
        await handle.ToUniTask();

        if (handle.Status == AsyncOperationStatus.Succeeded)
        {
            _loadedScenes.Add(sceneKey, new LoadedSceneData(handle));
            
            // Если режим Single, Unity выгружает остальные сцены автоматически,
            // очистим наш внутренний словарь от выгруженных сцен.
            if (loadMode == LoadSceneMode.Single)
            {
                CleanUpSingleModeExcept(sceneKey);
            }
        }
        else
        {
            Debug.LogError("Failed to load scene: " + sceneKey);
        }
    }

    public static async UniTask UnloadSceneAsync(string sceneKey)
    {
        if (!_loadedScenes.TryGetValue(sceneKey, out LoadedSceneData data))
        {
            Debug.LogWarning("Scene " + sceneKey + " was not loaded through this loader!");
            return;
        }

        data.RefCount--;
        Debug.Log("Scene " + sceneKey + " ref count decreased to: " + data.RefCount);

        if (data.RefCount <= 0)
        {
            Debug.Log("Unloading Scene via Addressables: " + sceneKey);
            
            AsyncOperationHandle<SceneInstance> unloadHandle = Addressables.UnloadSceneAsync(data.Handle);
            await unloadHandle.ToUniTask();
            
            _loadedScenes.Remove(sceneKey);
        }
    }

    private static void CleanUpSingleModeExcept(string keptSceneKey)
    {
        List<string> keysToRemove = new List<string>();
        foreach (var pair in _loadedScenes)
        {
            if (pair.Key != keptSceneKey)
            {
                keysToRemove.Add(pair.Key);
            }
        }

        foreach (string key in keysToRemove)
        {
            _loadedScenes.Remove(key);
        }
        Debug.Log("Cleaned up loaded scenes cache for Single mode. Active scene: " + keptSceneKey);
    }
}
```

#### Шаг 4.2: Обновление `GameplayBootstrap` и `SceneSwitcher` под UniTask
Переводим вызовы на асинхронные таски. Изменяется файл `GameplayBootstrap.cs`:

```csharp
using Cysharp.Threading.Tasks;
using UnityEngine;

public class GameplayBootstrap : Bootstrap
{
    private int _currentLevelIndex;

    public override void Initialize(ISceneArgs args)
    {
        if (args is GameplayArgs gameplayArgs)
        {
            _currentLevelIndex = gameplayArgs.LevelIndex;
            Debug.Log("Gameplay Scene initialized for Level: " + _currentLevelIndex);
        }
    }

    // Дополнительный асинхронный метод инициализации для примера
    public async UniTask InitializeAsync(ISceneArgs args)
    {
        if (args is GameplayArgs gameplayArgs)
        {
            _currentLevelIndex = gameplayArgs.LevelIndex;
            Debug.Log("Gameplay Scene Async Init Started...");
            
            // Имитируем тяжелую асинхронную операцию
            await UniTask.Delay(1000);
            
            Debug.Log("Gameplay Scene Async Init Complete.");
        }
    }
}
```

Изменяется файл `SceneSwitcher.cs` для работы с Addressables и UniTask:

```csharp
using Cysharp.Threading.Tasks;
using UnityEngine;
using UnityEngine.SceneManagement;

public class SceneSwitcher : MonoBehaviour
{
    [SerializeField] private string _targetSceneAddressableKey = "GameplayScene";
    [SerializeField] private LoadingScreen _loadingScreen;
    [SerializeField] private int _targetLevelIndex = 2;

    private void Update()
    {
        if (Input.GetKeyDown(KeyCode.Space))
        {
            ExecuteTransition().Forget();
        }
    }

    private async UniTaskVoid ExecuteTransition()
    {
        _loadingScreen.Show("Загрузка через Addressables...");

        // Загружаем основную сцену
        await AddressablesSceneLoader.LoadSceneAsync(_targetSceneAddressableKey, LoadSceneMode.Single);

        // Передаем аргументы через бутстрап
        GameplayBootstrap bootstrap = Object.FindAnyObjectByType<GameplayBootstrap>();
        if (bootstrap != null)
        {
            GameplayArgs args = new GameplayArgs(_targetLevelIndex);
            await bootstrap.InitializeAsync(args);
        }

        _loadingScreen.Hide();
    }
}
```

