### Часть 5: Автоматизация запуска Бутсцены в редакторе (Editor Tooling)

Для удобства тестирования мы напишем редакторский скрипт. Он автоматически загрузит бутсцену (сцену с индексом 0) при нажатии кнопки Play в Unity Editor, даже если разработчик находился на сцене геймплея.

#### Шаг 5.1: Создание скрипта `PlayModeBootLoader`
Этот скрипт должен лежать в специальной папке `Editor/`. Создается файл `Assets/Editor/PlayModeBootLoader.cs`:

```csharp
#if UNITY_EDITOR
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

[InitializeOnLoad]
public static class PlayModeBootLoader
{
    private const string MenuPath = "Tools/Force Boot Scene on Play";
    private const string EditorPrefKey = "ForceBootSceneOnPlay";

    static PlayModeBootLoader()
    {
        EditorApplication.delayCall += ApplySettings;
    }

    [MenuItem(MenuPath)]
    public static void ToggleAction()
    {
        bool isEnabled = EditorPrefs.GetBool(EditorPrefKey, true);
        EditorPrefs.SetBool(EditorPrefKey, !isEnabled);
        Menu.SetChecked(MenuPath, !isEnabled);
        ApplySettings();
        Debug.Log("Force Boot Scene on Play set to: " + (!isEnabled));
    }

    [MenuItem(MenuPath, true)]
    public static bool ToggleActionValidate()
    {
        Menu.SetChecked(MenuPath, EditorPrefs.GetBool(EditorPrefKey, true));
        return true;
    }

    private static void ApplySettings()
    {
        bool forceBoot = EditorPrefs.GetBool(EditorPrefKey, true);
        if (forceBoot)
        {
            // Берем сцену с индексом 0 в настройках билда
            if (EditorBuildSettings.scenes.Length > 0)
            {
                string bootScenePath = EditorBuildSettings.scenes[0].path;
                SceneAsset bootScene = AssetDatabase.LoadAssetAtPath<SceneAsset>(bootScenePath);
                if (bootScene != null)
                {
                    EditorSceneManager.playModeStartScene = bootScene;
                }
            }
        }
        else
        {
            EditorSceneManager.playModeStartScene = null;
        }
    }
}
#endif
```

