## 3. Пошаговый гайд по реализации

### Шаг 1: Определение контрактов и корутин-раннера

Создадим интерфейсы для инициализации и запуска корутин из C#-классов, а также класс-обертку, выступающий в роли исполнителя корутин.

```csharp
using System.Collections;
using UnityEngine;

namespace KBP.ARCHITECTURE.TRANSCRIPTS
{
    // Интерфейс для объектов, требующих контролируемой инициализации
    public interface IInitializable
    {
        void Initialize();
    }

    // Интерфейс для запуска корутин из не-MonoBehaviour классов
    public interface ICoroutineRunner
    {
        Coroutine StartCoroutine(IEnumerator routine);
        void StopCoroutine(Coroutine routine);
        void StopCoroutine(IEnumerator routine);
    }

    // Простой компонент-исполнитель корутин
    public sealed class CoroutineRunner : MonoBehaviour, ICoroutineRunner
    {
        // Класс пустой, используется только как мост к MonoBehaviour.StartCoroutine
    }
}
```

### Шаг 2: Реализация чистой логики таймера и его конфигурации

Создаем `TimerConfig` в виде `ScriptableObject` для хранения параметров и класс `Timer` в виде чистого C#-класса, использующего события и `ICoroutineRunner`.

```csharp
using System;
using System.Collections;
using UnityEngine;

namespace KBP.ARCHITECTURE.TRANSCRIPTS
{
    // ScriptableObject - только для хранения статических настроек
    [CreateAssetMenu(fileName = "NewTimerConfig", menuName = "Configs/Timer Config")]
    public sealed class TimerConfig : ScriptableObject
    {
        [SerializeField] private float _duration = 10f;
        
        public float Duration => _duration;
    }

    // Чистый C#-класс для бизнес-логики таймера
    public sealed class Timer
    {
        private readonly ICoroutineRunner _coroutineRunner;
        private readonly float _duration;
        
        private float _remainingTime;
        private Coroutine _timerCoroutine;

        // События для уведомления UI и внешних систем
        public event Action<float> OnTimeChanged; // Передает оставшееся время (в процентах от 0 до 1)
        public event Action OnCompleted;

        public float RemainingTime => _remainingTime;
        public float Duration => _duration;

        public Timer(TimerConfig config, ICoroutineRunner coroutineRunner)
        {
            _duration = config.Duration;
            _remainingTime = _duration;
            _coroutineRunner = coroutineRunner ?? throw new ArgumentNullException(nameof(coroutineRunner));
        }

        public void Start()
        {
            Stop();
            _timerCoroutine = _coroutineRunner.StartCoroutine(TimerRoutine());
        }

        public void Stop()
        {
            if (_timerCoroutine != null)
            {
                _coroutineRunner.StopCoroutine(_timerCoroutine);
                _timerCoroutine = null;
            }
        }

        private IEnumerator TimerRoutine()
        {
            _remainingTime = _duration;
            
            while (_remainingTime > 0f)
            {
                _remainingTime -= Time.deltaTime;
                if (_remainingTime < 0f) _remainingTime = 0f;
                
                // Генерируем событие изменения времени
                float progress = _remainingTime / _duration;
                OnTimeChanged?.Invoke(progress);
                
                yield return null;
            }

            _timerCoroutine = null;
            OnCompleted?.Invoke();
        }
    }
}
```

### Шаг 3: Реализация визуальной части (View)

Создаем базовый абстрактный класс полоски и конкретную реализацию `TimeBar`, управляющую шкалой на экране.

```csharp
using UnityEngine;
using UnityEngine.UI;

namespace KBP.ARCHITECTURE.TRANSCRIPTS
{
    // Абстрактный базовый класс для заполняемых шкал
    [RequireComponent(typeof(Image))]
    public abstract class FillableBar : MonoBehaviour
    {
        [SerializeField] protected Image fillImage;

        protected virtual void Awake()
        {
            if (fillImage == null)
            {
                fillImage = GetComponent<Image>();
            }
        }

        public virtual void UpdateFill(float progress)
        {
            if (fillImage != null)
            {
                fillImage.fillAmount = Mathf.Clamp01(progress);
            }
        }
    }

    // Конкретное представление таймера
    public sealed class TimeBar : FillableBar
    {
        private Timer _timer;

        // Явная инициализация зависимостей через метод вместо Awake/Start
        public void Initialize(Timer timer)
        {
            Deinitialize();

            _timer = timer;
            
            if (_timer != null)
            {
                _timer.OnTimeChanged += HandleTimeChanged;
                _timer.OnCompleted += HandleTimeCompleted;
                // Устанавливаем начальное состояние
                UpdateFill(_timer.RemainingTime / _timer.Duration);
            }
        }

        private void OnDestroy()
        {
            Deinitialize();
        }

        private void Deinitialize()
        {
            if (_timer != null)
            {
                _timer.OnTimeChanged -= HandleTimeChanged;
                _timer.OnCompleted -= HandleTimeCompleted;
                _timer = null;
            }
        }

        private void HandleTimeChanged(float progress)
        {
            UpdateFill(progress);
        }

        private void HandleTimeCompleted()
        {
            UpdateFill(0f);
            Debug.Log("[TimeBar] Таймер успешно завершил отсчет!");
        }
    }
}
```

### Шаг 4: Реализация примера зависимых сервисов (Лабиринт и Ловушки)

Покажем, как единая точка входа решает проблему очередности инициализации на примере `Maze` и `TrapGenerator`.

```csharp
using UnityEngine;

namespace KBP.ARCHITECTURE.TRANSCRIPTS
{
    public sealed class Maze : MonoBehaviour, IInitializable
    {
        public bool IsGenerated { get; private set; }

        public void Initialize()
        {
            // Симуляция генерации лабиринта
            IsGenerated = true;
            Debug.Log("[Maze] Лабиринт сгенерирован и готов к расстановке ловушек.");
        }
    }

    public sealed class TrapGenerator : MonoBehaviour
    {
        private Maze _maze;
        public bool TrapsPlaced { get; private set; }

        // Зависимость передается явно при инициализации
        public void Initialize(Maze maze)
        {
            _maze = maze;

            if (_maze == null)
            {
                Debug.LogError("[TrapGenerator] Ошибка: Лабиринт не передан!");
                return;
            }

            if (!_maze.IsGenerated)
            {
                Debug.LogError("[TrapGenerator] Ошибка: Попытка сгенерировать ловушки на не готовом лабиринте!");
                return;
            }

            // Логика расстановки ловушек на лабиринте
            TrapsPlaced = true;
            Debug.Log("[TrapGenerator] Ловушки успешно расставлены на лабиринте.");
        }
    }
}
```

### Шаг 5: Создание единой точки входа (Bootstrap)

Создаем класс `Bootstrap`, который связывает все компоненты воедино, запускает инициализацию в строгой очередности и связывает логику таймера с его отображением.

```csharp
using UnityEngine;

namespace KBP.ARCHITECTURE.TRANSCRIPTS
{
    public sealed class Bootstrap : MonoBehaviour
    {
        [Header("Scene Dependencies")]
        [SerializeField] private Maze _maze;
        [SerializeField] private TrapGenerator _trapGenerator;
        [SerializeField] private TimeBar _timeBar;

        [Header("Configs")]
        [SerializeField] private TimerConfig _timerConfig;

        private CoroutineRunner _coroutineRunner;
        private Timer _timer;

        private void Awake()
        {
            Debug.Log("[Bootstrap] Запуск инициализации сцены...");

            // 1. Создаем инфраструктурные сервисы
            GameObject runnerObject = new GameObject("[Coroutine Runner]");
            runnerObject.transform.SetParent(transform);
            _coroutineRunner = runnerObject.AddComponent<CoroutineRunner>();

            // 2. Инициализируем Лабиринт
            if (_maze != null)
            {
                _maze.Initialize();
            }

            // 3. Инициализируем Генератор Ловушек, передавая ему готовый Лабиринт
            if (_trapGenerator != null)
            {
                _trapGenerator.Initialize(_maze);
            }

            // 4. Создаем C#-логику таймера (не-MonoBehaviour), передавая конфиг и ранер корутин
            if (_timerConfig != null)
            {
                _timer = new Timer(_timerConfig, _coroutineRunner);
                
                // Подписываемся на завершение таймера для запуска дополнительной логики
                _timer.OnCompleted += OnTimerFinished;
            }
            else
            {
                Debug.LogError("[Bootstrap] Не задан TimerConfig!");
            }

            // 5. Инициализируем UI-компоненты (View) и связываем их с логикой (Model)
            if (_timeBar != null && _timer != null)
            {
                _timeBar.Initialize(_timer);
            }

            // 6. Запускаем рантайм-процессы
            if (_timer != null)
            {
                Debug.Log("[Bootstrap] Запуск таймера...");
                _timer.Start();
            }

            Debug.Log("[Bootstrap] Инициализация сцены успешно завершена.");
        }

        private void OnTimerFinished()
        {
            Debug.Log("[Bootstrap] Действие по завершению таймера (например, проигрыш или переход на другой уровень).");
        }

        private void OnDestroy()
        {
            if (_timer != null)
            {
                _timer.OnCompleted -= OnTimerFinished;
                _timer.Stop();
            }
        }
    }
}
```

