### Часть 3: Внедрение `MineConfig` на ScriptableObject и паттерн Bootstrap

Настройки мины зашиты прямо в MonoBehaviour. Если на сцене 100 мин, менять урон для каждой вручную неудобно. Мы выносим параметры в `ScriptableObject` и делаем запуск мины контролируемым из кода.

#### Шаг 3.1: Создание конфигурации `MineConfig`
Параметры хранятся как ассет проекта. Создается файл `MineConfig.cs`:

```csharp
using UnityEngine;

[CreateAssetMenu(fileName = "MineConfig", menuName = "Configs/MineConfig")]
public class MineConfig : ScriptableObject
{
    [SerializeField] private float _detectRadius = 3f;
    [SerializeField] private float _delayBeforeExplosion = 2f;
    [SerializeField] private int _damage = 40;

    public float DetectRadius => _detectRadius;
    public float DelayBeforeExplosion => _delayBeforeExplosion;
    public int Damage => _damage;
}
```

#### Шаг 3.2: Рефакторинг мины для поддержки `Initialize`
Мина больше не настраивает коллайдер в `Awake`. Она ждет вызова внешнего метода. Создается файл `ConfiguredMine.cs`:

```csharp
using System.Collections;
using UnityEngine;

public class ConfiguredMine : MonoBehaviour
{
    [SerializeField] private SphereCollider _triggerCollider;

    private float _detectRadius;
    private float _delayBeforeExplosion;
    private int _damage;
    
    private bool _isInitialized = false;
    private bool _isDetonationStarted = false;

    public void Initialize(MineConfig config)
    {
        _detectRadius = config.DetectRadius;
        _delayBeforeExplosion = config.DelayBeforeExplosion;
        _damage = config.Damage;

        if (_triggerCollider != null)
        {
            _triggerCollider.radius = _detectRadius;
            _triggerCollider.isTrigger = true;
        }

        _isInitialized = true;
        Debug.Log("Mine initialized with radius: " + _detectRadius + ", delay: " + _delayBeforeExplosion);
    }

    private void OnTriggerEnter(Collider other)
    {
        if (!_isInitialized || _isDetonationStarted)
        {
            return;
        }

        IDamageable damageable = other.GetComponent<IDamageable>();
        if (damageable != null)
        {
            StartCoroutine(DetonationRoutine());
        }
    }

    private IEnumerator DetonationRoutine()
    {
        _isDetonationStarted = true;
        Debug.Log("Detonation sequence activated...");
        
        yield return new WaitForSeconds(_delayBeforeExplosion);
        
        Explode();
    }

    private void Explode()
    {
        Debug.Log("Explosion!");
        
        Collider[] colliders = Physics.OverlapSphere(transform.position, _detectRadius);
        foreach (Collider hit in colliders)
        {
            IDamageable damageable = hit.GetComponent<IDamageable>();
            if (damageable != null)
            {
                damageable.TakeDamage(_damage);
            }
        }

        Destroy(gameObject);
    }

    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.red;
        Gizmos.DrawWireSphere(transform.position, _detectRadius);
    }
}
```

#### Шаг 3.3: Создание класса управления `Bootstrap`
Bootstrap динамически спавнит мины на сцене и передает им нужный конфигурационный файл. Создается файл `Bootstrap.cs`:

```csharp
using UnityEngine;

public class Bootstrap : MonoBehaviour
{
    [SerializeField] private ConfiguredMine _minePrefab;
    [SerializeField] private MineConfig _easyLevelMineConfig;
    [SerializeField] private MineConfig _hardLevelMineConfig;
    
    [SerializeField] private Transform _spawnPoint1;
    [SerializeField] private Transform _spawnPoint2;

    private void Start()
    {
        SpawnAndInitializeMine(_spawnPoint1.position, _easyLevelMineConfig);
        SpawnAndInitializeMine(_spawnPoint2.position, _hardLevelMineConfig);
    }

    private void SpawnAndInitializeMine(Vector3 position, MineConfig config)
    {
        ConfiguredMine newMine = Instantiate(_minePrefab, position, Quaternion.identity);
        newMine.Initialize(config);
    }
}
```

