#### Шаг 4.5: Рефакторинг `CompositeMineConfig`
Конфиг мины теперь хранит не конкретный урон, а список воздействий, которые будут применены при детонации. Создается файл `CompositeMineConfig.cs`:

```csharp
using UnityEngine;

[CreateAssetMenu(fileName = "CompositeMineConfig", menuName = "Configs/CompositeMineConfig")]
public class CompositeMineConfig : ScriptableObject
{
    [SerializeField] private float _detectRadius = 3f;
    [SerializeField] private float _delayBeforeExplosion = 2f;
    [SerializeField] private EffectConfig[] _effects;

    public float DetectRadius => _detectRadius;
    public float DelayBeforeExplosion => _delayBeforeExplosion;
    public EffectConfig[] Effects => _effects;
}
```

#### Шаг 4.6: Финальная композитная мина `CompositeMine`
Мина инициализируется списком эффектов и выполняет их при детонации на всех целях в радиусе. Создается файл `CompositeMine.cs`:

```csharp
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class CompositeMine : MonoBehaviour
{
    [SerializeField] private SphereCollider _triggerCollider;

    private float _detectRadius;
    private float _delayBeforeExplosion;
    private List<IEffect> _effectsOnExplode = new List<IEffect>();
    
    private bool _isInitialized = false;
    private bool _isDetonationStarted = false;

    public void Initialize(CompositeMineConfig config)
    {
        _detectRadius = config.DetectRadius;
        _delayBeforeExplosion = config.DelayBeforeExplosion;

        _effectsOnExplode.Clear();
        foreach (EffectConfig effectConfig in config.Effects)
        {
            if (effectConfig != null)
            {
                _effectsOnExplode.Add(effectConfig.CreateEffect());
            }
        }

        if (_triggerCollider != null)
        {
            _triggerCollider.radius = _detectRadius;
            _triggerCollider.isTrigger = true;
        }

        _isInitialized = true;
        Debug.Log("Composite mine initialized with " + _effectsOnExplode.Count + " effects.");
    }

    private void OnTriggerEnter(Collider other)
    {
        if (!_isInitialized || _isDetonationStarted)
        {
            return;
        }

        // Мина активируется, если объект может получить урон (IDamageable)
        IDamageable damageable = other.GetComponent<IDamageable>();
        if (damageable != null)
        {
            StartCoroutine(DetonationRoutine());
        }
    }

    private IEnumerator DetonationRoutine()
    {
        _isDetonationStarted = true;
        Debug.Log("Composite mine countdown started...");
        
        yield return new WaitForSeconds(_delayBeforeExplosion);
        
        Explode();
    }

    private void Explode()
    {
        Debug.Log("Composite BOOM!");
        
        Collider[] colliders = Physics.OverlapSphere(transform.position, _detectRadius);
        
        foreach (Collider hit in colliders)
        {
            foreach (IEffect effect in _effectsOnExplode)
            {
                effect.Execute(hit.gameObject);
            }
        }

        Destroy(gameObject);
    }

    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.red;
        Gizmos.DrawWireSphere(transform.position, _detectRadius);
    }
}
```

